package mz.bam.seeky.android;
import java.io.*;import com.tom_roush.pdfbox.pdmodel.*;import com.tom_roush.pdfbox.android.PDFBoxResourceLoader;
public class PdfIndexCheck {
 public static void main(String[] args)throws Exception{PDFBoxResourceLoader.init(new android.content.Context());File fixture=new File(args[0]),cache=fixture.getParentFile();PdfIndexText.Result result=PdfIndexText.read(fixture,cache,()->false);if(result.pages!=3||result.truncated||!result.text.contains("Deep search second page"))throw new AssertionError("real PDF index");System.out.println("PASS actual bounded PDF index extracts all fixture pages");boolean cancelled=false;try{PdfIndexText.read(fixture,cache,()->true);}catch(InterruptedIOException e){cancelled=true;}if(!cancelled)throw new AssertionError("cancel");System.out.println("PASS PDF indexing cancellation before extraction");File many=new File(cache,"many.pdf");try(PDDocument doc=PDDocument.load(fixture)){for(int i=0;i<80;i++)doc.addPage(new PDPage());doc.save(many);}result=PdfIndexText.read(many,cache,()->false);if(!result.truncated||result.pages!=80||result.total!=83)throw new AssertionError("page limit");System.out.println("PASS long PDF returns explicit partial-index status at 80 pages");PdfIndexText.Output output=new PdfIndexText.Output();boolean limited=false;try{output.write(new char[300000],0,300000);}catch(PdfIndexText.Limit e){limited=true;}if(!limited||output.text.length()!=262144)throw new AssertionError("text cap");System.out.println("PASS extraction output cannot exceed 256K characters");}
}